export function updateMech(v, keys, dt, now, cfg) {
  const wantsSprint = (keys.ShiftLeft || keys.ShiftRight) && keys.forward;
  if (wantsSprint && v.energy > 0 && now >= v.lockUntil) v.sprinting = true;
  if (!wantsSprint || v.energy <= 0) {
    if (v.sprinting) v.lockUntil = now + cfg.cooldown;
    v.sprinting = false;
  }
  if (v.sprinting) {
    v.energy = Math.max(0, v.energy - cfg.drain * dt);
    v.regenDelay = cfg.delay;
    if (v.energy <= 0) { v.sprinting = false; v.lockUntil = now + cfg.cooldown; }
  } else if (v.regenDelay > 0) v.regenDelay -= dt;
  else v.energy = Math.min(cfg.capacity, v.energy + cfg.regen * dt);
  v.speed = cfg.speed * (v.sprinting ? cfg.multiplier : 1);
}

